package io.zingg.duckdb.engine;
public record ResourceBudget(long memoryLimitBytes,long maxRows,long maxSpillBytes){ public ResourceBudget{if(memoryLimitBytes<0||maxRows<0||maxSpillBytes<0)throw new IllegalArgumentException("resource limits cannot be negative");} public static ResourceBudget unlimited(){return new ResourceBudget(0,0,0);} public void enforceRows(long rows){if(maxRows>0&&rows>maxRows)throw new io.zingg.duckdb.api.DuckException("row budget exceeded: "+rows+" > "+maxRows);} public void enforceBytes(long bytes){if(maxSpillBytes>0&&bytes>maxSpillBytes)throw new io.zingg.duckdb.api.DuckException("byte budget exceeded: "+bytes+" > "+maxSpillBytes);} }
